        "answers": [
          "D"
        ],
        "confidence": "preference",
        "basis": "clinical",
        "explanation": "D is the likely intended choice because severe hypertension can damage the choroidal circulation and cause an exudative retinal detachment. This is an uncommon complication of markedly elevated or malignant hypertension, not the usual complication of every patient with uncontrolled blood pressure. The stem gives no blood-pressure level, visual symptoms, or fundus findings, so the claim that it is the most likely complication is weak.",
