        "confidence": "preference",
        "basis": "lecture",
        "explanation": "Early diabetic kidney disease is often detected by moderately increased urine albumin before eGFR falls. The intended D corresponds to an albumin-to-creatinine ratio of 30–300 mg/g, ideally confirmed on repeat testing. The source writes mg/L, which is an albumin concentration rather than the proper unit for an albumin-to-creatinine ratio.",
