        "explanation": "Systemic sclerosis with new severe hypertension and marked kidney impairment strongly suggests scleroderma renal crisis. Captopril, an ACE inhibitor, directly treats the renin-driven process and should be started promptly. Pulmonary congestion may also need a diuretic, and dialysis may be required for standard urgent indications, but neither replaces ACE inhibition.",
