        "interpretation": "A rising creatinine in SLE requires prompt evaluation for lupus nephritis and other causes of AKI. Urinalysis, urine protein, the kidney-function trend, and often a kidney biopsy guide treatment. Steroids may be part of treatment for active nephritis, but a creatinine rise alone does not justify automatic high-dose steroid treatment or establish a need for dialysis."
