        "answers": [
          "D"
        ],
        "confidence": "preference",
        "basis": "lecture",
        "explanation": "Hypertension with marked hypokalemia raises suspicion for primary aldosteronism, so the aldosterone-to-renin ratio is the best listed screening test. Potassium 2.3 mmol/L also requires prompt clinical assessment, ECG review, and replacement. Correct hypokalemia and account for interfering medicines before interpreting the ratio, because low potassium can suppress aldosterone and produce a misleading result.",
