        "explanation": "Persistent bloody diarrhea, anemia and high inflammatory markers suggest inflammatory bowel disease, particularly ulcerative colitis, after infection has been assessed. Lower endoscopy with biopsies is the next diagnostic approach, making B the best listed option. Because 15 bloody stools a day with anemia may indicate severe colitis, clinical assessment is urgent and a limited flexible sigmoidoscopy may be safer than a full colonoscopy during an acute severe episode.",
