        "confidence": "preference",
        "basis": "clinical",
        "explanation": "A first unprovoked DVT at a young age, together with a family history, makes thrombophilia the intended topic. Among these options, a thrombophilia screen is the relevant investigation; chest imaging is not routinely needed without PE symptoms. In practice, testing is selective and should be ordered only when the result could change treatment or counseling.",
