        "confidence": "supported",
        "basis": "lecture",
        "explanation": "A systolic pressure of 80 mmHg indicates hemodynamic instability in a patient with PE. This is the setting in which thrombolysis may be needed to restore pulmonary blood flow, after checking bleeding contraindications. A large clot in a stable, asymptomatic patient is not by itself an indication for thrombolysis.",
