        "confidence": "preference",
        "basis": "lecture",
        "explanation": "Chronic cough, hemoptysis, weight loss, and a lung mass in a heavy smoker make lung cancer a major concern. Tissue sampling is needed, and bronchoscopy with biopsy is the best listed option when the lesion is accessible through the airways. A peripheral mass touching the pleura may instead be sampled by image-guided biopsy, so the exact route depends on its location.",
