        "explanation": "The smoking history, barrel chest, and hyperinflated lungs suggest COPD. Spirometry is required to confirm persistent airflow obstruction, using the post-bronchodilator FEV1/FVC ratio. Chest X-ray and blood gases can show consequences of the disease but do not replace diagnostic spirometry.",
