          "title": "Acute Coronary Syndrome",
          "page": 4,
          "quote": "During evolution of an atherosclerotic plaque, monocytes and other inflammatory cells bind to receptors expressed by endothelial cells. Subsequently, they migrate into the intima, and take up oxidised low-density lipoprotein (LDL) particles by phagocytosis to become lipid-laden macrophages or foam cells.",
