        "confidence": "preference",
        "basis": "lecture",
        "explanation": "Recurrent chest infections, sinusitis, and bronchiectasis can occur in both cystic fibrosis and primary ciliary dyskinesia. The word azoospermia favors cystic fibrosis, which commonly causes absent or obstructed sperm ducts; primary ciliary dyskinesia mainly causes poorly motile sperm. Lower-lobe disease points toward ciliary dysfunction, but it does not outweigh that distinction by itself.",
