          "title": "Investigation of Lung Disease",
          "page": 17,
          "quote": "The conditions takes an insidious course that initially presents with exertional dyspnea that progresses to dyspnea at rest, persistent nonproductive cough, and fatigue. Recall from pathology 443 : Radiologic finding: 1.subpleural and basilar involvement (apico-basal gradient ) 2.reticular abnormalities and cyst changes 3.honeycombing. On auscultation crackles might be heard.",
          "relation": "teaching",
