        "confidence": "preference",
        "basis": "clinical",
        "explanation": "Recurrent DVT in a 25-year-old without a stated transient trigger is the strongest reason among these choices to consider an inherited predisposition. A fracture, surgery, or established heart failure can instead provide an acquired explanation for thrombosis. Testing is still selective and useful only if the result could change management.",
        "objection": "A young age or recurrence is not an automatic instruction to test every patient; long-term treatment decisions may already be clear without a panel.",
