          "title": "Pulmonary Embolism",
          "page": 5,
          "quote": "Alterations in the coagulation-fibrinolytic system 438: (increase the chances of clot formation). eg. Deficiency in protein S or C or the presence of factor leiden 5 (mutated form of Factor 5), COVID-19 increase risk of thrombosis.",
