        "confidence": "supported",
        "basis": "lecture",
        "explanation": "Beta blockers lower heart rate and contractility, reducing the heart muscle’s oxygen demand. Antiplatelet and anticoagulant drugs act mainly on clot formation instead. In an inferior MI, beta blockers are used only after checking for hypotension, bradycardia, AV block, or other contraindications.",
